diff --git a/lib/chatComposerDraftCore.ts b/lib/chatComposerDraftCore.ts
new file mode 100644
index 00000000..da0678fa
--- /dev/null
+++ b/lib/chatComposerDraftCore.ts
@@ -0,0 +1,125 @@
+import { z } from "zod";
+
+export const CHAT_DRAFT_NEW_SCOPE = "new" as const;
+export const CHAT_DRAFT_REVISION_CONFLICT = "CHAT_DRAFT_REVISION_CONFLICT" as const;
+export const CHAT_DRAFT_INVALID = "CHAT_DRAFT_INVALID" as const;
+
+const opaqueId = z.string().trim().min(1).max(64).regex(/^[A-Za-z0-9_-]+$/);
+
+export const chatDraftScopeKeySchema = opaqueId.refine(
+  (value) => value === CHAT_DRAFT_NEW_SCOPE || !value.startsWith("guest_"),
+  "A durable draft must use the new scope or an account conversation id."
+);
+
+const uploadReferenceSchema = z.object({ uploadId: opaqueId }).strict();
+const attachmentReferenceSchema = z.object({ attachmentId: opaqueId }).strict();
+
+export const chatDraftAttachmentReferenceSchema = z.union([
+  uploadReferenceSchema,
+  attachmentReferenceSchema,
+]);
+
+export type ChatDraftAttachmentReference = z.infer<
+  typeof chatDraftAttachmentReferenceSchema
+>;
+
+export const chatDraftAttachmentReferencesSchema = z
+  .array(chatDraftAttachmentReferenceSchema)
+  .max(5)
+  .superRefine((references, context) => {
+    const seen = new Set<string>();
+    for (const [index, reference] of references.entries()) {
+      const identity =
+        "uploadId" in reference
+          ? `upload:${reference.uploadId}`
+          : `attachment:${reference.attachmentId}`;
+      if (seen.has(identity)) {
+        context.addIssue({
+          code: "custom",
+          message: "Attachment references must be unique and ordered.",
+          path: [index],
+        });
+      }
+      seen.add(identity);
+    }
+  });
+
+export const chatComposerDraftPutSchema = z
+  .object({
+    expectedRevision: z.number().int().min(0).max(2_147_483_646),
+    text: z.string().max(50_000),
+    attachmentReferences: chatDraftAttachmentReferencesSchema,
+  })
+  .strict();
+
+export const chatComposerDraftDeleteSchema = z
+  .object({
+    expectedRevision: z.number().int().min(1).max(2_147_483_647),
+  })
+  .strict();
+
+export type ChatComposerDraftPut = z.infer<typeof chatComposerDraftPutSchema>;
+
+export type ChatComposerDraftRecord = {
+  scopeKey: string;
+  conversationId: string | null;
+  text: string;
+  attachmentReferences: ChatDraftAttachmentReference[];
+  revision: number;
+  createdAt: Date;
+  updatedAt: Date;
+};
+
+export type DraftCasDecision =
+  | { action: "create"; nextRevision: 1 }
+  | { action: "update"; nextRevision: number }
+  | { action: "conflict"; currentRevision: number | null };
+
+export function decideDraftCas(
+  currentRevision: number | null,
+  expectedRevision: number
+): DraftCasDecision {
+  if (currentRevision === null) {
+    return expectedRevision === 0
+      ? { action: "create", nextRevision: 1 }
+      : { action: "conflict", currentRevision: null };
+  }
+  if (expectedRevision !== currentRevision || currentRevision >= 2_147_483_647) {
+    return { action: "conflict", currentRevision };
+  }
+  return { action: "update", nextRevision: currentRevision + 1 };
+}
+export function draftConversationId(scopeKey: string): string | null {
+  return scopeKey === CHAT_DRAFT_NEW_SCOPE ? null : scopeKey;
+}
+
+export function validateDraftReferencesForScope(
+  scopeKey: string,
+  references: readonly ChatDraftAttachmentReference[]
+): boolean {
+  return (
+    scopeKey !== CHAT_DRAFT_NEW_SCOPE ||
+    references.every((reference) => "uploadId" in reference)
+  );
+}
+
+export function parseStoredDraftReferences(
+  value: unknown
+): ChatDraftAttachmentReference[] {
+  const parsed = chatDraftAttachmentReferencesSchema.safeParse(value);
+  if (!parsed.success) {
+    throw new Error("Stored Chat composer draft references are unreadable.");
+  }
+  return parsed.data;
+}
+
+export function publicChatComposerDraft(record: ChatComposerDraftRecord) {
+  return {
+    scopeKey: record.scopeKey,
+    text: record.text,
+    attachmentReferences: record.attachmentReferences,
+    revision: record.revision,
+    createdAt: record.createdAt.toISOString(),
+    updatedAt: record.updatedAt.toISOString(),
+  };
+}
diff --git a/lib/chatComposerDraftPersistence.ts b/lib/chatComposerDraftPersistence.ts
new file mode 100644
index 00000000..f530e938
--- /dev/null
+++ b/lib/chatComposerDraftPersistence.ts
@@ -0,0 +1,213 @@
+import "server-only";
+
+import type { Prisma } from "@prisma/client";
+
+import {
+  CHAT_DRAFT_REVISION_CONFLICT,
+  decideDraftCas,
+  draftConversationId,
+  parseStoredDraftReferences,
+  publicChatComposerDraft,
+  type ChatComposerDraftPut,
+} from "@/lib/chatComposerDraftCore";
+import {
+  accountAttachmentPrefix,
+  resolveMessageAttachmentReferences,
+} from "@/lib/messageAttachmentStorage";
+import { prisma } from "@/lib/prisma";
+
+const DRAFT_SELECT = {
+  scopeKey: true,
+  conversationId: true,
+  text: true,
+  attachmentReferences: true,
+  revision: true,
+  createdAt: true,
+  updatedAt: true,
+} as const;
+
+export class ChatDraftRevisionConflictError extends Error {
+  readonly code = CHAT_DRAFT_REVISION_CONFLICT;
+
+  constructor(readonly currentRevision: number | null) {
+    super("The Chat draft changed before this request was applied.");
+    this.name = "ChatDraftRevisionConflictError";
+  }
+}
+const normalizeDraftRow = (row: {
+  scopeKey: string;
+  conversationId: string | null;
+  text: string;
+  attachmentReferences: Prisma.JsonValue;
+  revision: number;
+  createdAt: Date;
+  updatedAt: Date;
+}) => ({
+  ...row,
+  attachmentReferences: parseStoredDraftReferences(row.attachmentReferences),
+});
+
+export async function readChatComposerDraft(userId: string, scopeKey: string) {
+  const row = await prisma.chatComposerDraft.findUnique({
+    where: { userId_scopeKey: { userId, scopeKey } },
+    select: DRAFT_SELECT,
+  });
+  return row ? normalizeDraftRow(row) : null;
+}
+
+export async function readPublicChatComposerDraft(input: {
+  userId: string;
+  userEmail: string | null | undefined;
+  scopeKey: string;
+}) {
+  const draft = await readChatComposerDraft(input.userId, input.scopeKey);
+  if (!draft) return null;
+  return publicChatComposerDraftWithAttachments({ ...input, draft });
+}
+
+export async function publicChatComposerDraftWithAttachments(input: {
+  userId: string;
+  userEmail: string | null | undefined;
+  draft: ReturnType<typeof normalizeDraftRow>;
+}) {
+  const { draft } = input;
+  if (draft.attachmentReferences.length === 0) {
+    return { ...publicChatComposerDraft(draft), attachments: [] };
+  }
+  if (!input.userEmail) {
+    throw new Error("CHAT_DRAFT_ATTACHMENT_ACCOUNT_ADDRESS_REQUIRED");
+  }
+  const resolved = await resolveMessageAttachmentReferences({
+    userId: input.userId,
+    ownPrefix: accountAttachmentPrefix(input.userEmail),
+    conversationId: draft.conversationId,
+    references: draft.attachmentReferences,
+  });
+  return {
+    ...publicChatComposerDraft(draft),
+    attachments: resolved.map((attachment, ordinal) => ({
+      id: attachment.attachmentId ?? attachment.uploadId!,
+      ordinal,
+      name: attachment.name,
+      mediaType: attachment.mediaType,
+      size: attachment.size,
+      kind: attachment.kind,
+      ...(attachment.attachmentId
+        ? { attachmentId: attachment.attachmentId }
+        : { uploadId: attachment.uploadId! }),
+      ...(attachment.unavailableAt
+        ? { unavailableAt: attachment.unavailableAt.toISOString() }
+        : {}),
+      ...(attachment.unavailableReason
+        ? { unavailableReason: attachment.unavailableReason }
+        : {}),
+    })),
+  };
+}
+
+async function validateAttachmentOwnership(input: {
+  userId: string;
+  userEmail: string | null | undefined;
+  scopeKey: string;
+  draft: ChatComposerDraftPut;
+}) {
+  if (input.draft.attachmentReferences.length === 0) return;
+  if (!input.userEmail) {
+    throw new Error("CHAT_DRAFT_ATTACHMENT_ACCOUNT_ADDRESS_REQUIRED");
+  }
+  await resolveMessageAttachmentReferences({
+    userId: input.userId,
+    ownPrefix: accountAttachmentPrefix(input.userEmail),
+    conversationId: draftConversationId(input.scopeKey),
+    references: input.draft.attachmentReferences,
+  });
+}
+
+export async function writeChatComposerDraft(input: {
+  userId: string;
+  userEmail: string | null | undefined;
+  scopeKey: string;
+  draft: ChatComposerDraftPut;
+}) {
+  await validateAttachmentOwnership(input);
+
+  const current = await prisma.chatComposerDraft.findUnique({
+    where: { userId_scopeKey: { userId: input.userId, scopeKey: input.scopeKey } },
+    select: { revision: true },
+  });
+  const decision = decideDraftCas(current?.revision ?? null, input.draft.expectedRevision);
+  if (decision.action === "conflict") {
+    throw new ChatDraftRevisionConflictError(decision.currentRevision);
+  }
+
+  const attachmentReferences = input.draft.attachmentReferences as Prisma.InputJsonValue;
+  if (decision.action === "create") {
+    try {
+      const created = await prisma.chatComposerDraft.create({
+        data: {
+          userId: input.userId,
+          scopeKey: input.scopeKey,
+          conversationId: draftConversationId(input.scopeKey),
+          text: input.draft.text,
+          attachmentReferences,
+          revision: decision.nextRevision,
+        },
+        select: DRAFT_SELECT,
+      });
+      return normalizeDraftRow(created);
+    } catch (error) {
+      if (error && typeof error === "object" && "code" in error && error.code === "P2002") {
+        const raced = await prisma.chatComposerDraft.findUnique({
+          where: { userId_scopeKey: { userId: input.userId, scopeKey: input.scopeKey } },
+          select: { revision: true },
+        });
+        throw new ChatDraftRevisionConflictError(raced?.revision ?? null);
+      }
+      throw error;
+    }
+  }
+
+  const updated = await prisma.chatComposerDraft.updateManyAndReturn({
+    where: {
+      userId: input.userId,
+      scopeKey: input.scopeKey,
+      revision: input.draft.expectedRevision,
+    },
+    data: {
+      text: input.draft.text,
+      attachmentReferences,
+      revision: decision.nextRevision,
+    },
+    select: DRAFT_SELECT,
+  });
+  if (updated.length !== 1) {
+    const raced = await prisma.chatComposerDraft.findUnique({
+      where: { userId_scopeKey: { userId: input.userId, scopeKey: input.scopeKey } },
+      select: { revision: true },
+    });
+    throw new ChatDraftRevisionConflictError(raced?.revision ?? null);
+  }
+
+  return normalizeDraftRow(updated[0]!);
+}
+
+export async function deleteChatComposerDraft(input: {
+  userId: string;
+  scopeKey: string;
+  expectedRevision: number;
+}) {
+  const deleted = await prisma.chatComposerDraft.deleteMany({
+    where: {
+      userId: input.userId,
+      scopeKey: input.scopeKey,
+      revision: input.expectedRevision,
+    },
+  });
+  if (deleted.count === 1) return;
+
+  const current = await prisma.chatComposerDraft.findUnique({
+    where: { userId_scopeKey: { userId: input.userId, scopeKey: input.scopeKey } },
+    select: { revision: true },
+  });
+  throw new ChatDraftRevisionConflictError(current?.revision ?? null);
+}
diff --git a/lib/chatDraftMessageConsume.ts b/lib/chatDraftMessageConsume.ts
new file mode 100644
index 00000000..0b5d6f1a
--- /dev/null
+++ b/lib/chatDraftMessageConsume.ts
@@ -0,0 +1,345 @@
+import "server-only";
+
+import type { Prisma } from "@prisma/client";
+import { z } from "zod";
+
+import {
+  CHAT_DRAFT_NEW_SCOPE,
+  chatDraftAttachmentReferencesSchema,
+  parseStoredDraftReferences,
+  type ChatDraftAttachmentReference,
+} from "@/lib/chatComposerDraftCore";
+import {
+  PUBLIC_MESSAGE_ATTACHMENT_SELECT,
+  toPublicMessageAttachment,
+  type PublicMessageAttachment,
+} from "@/lib/messageAttachmentCore";
+import { lockChatRecoveryConversation } from "@/lib/chatResponseAttemptPersistence";
+
+const opaqueId = z.string().trim().min(1).max(64).regex(/^[A-Za-z0-9_-]+$/);
+
+export const chatDraftConsumeRequestSchema = z
+  .object({
+    scopeKey: opaqueId,
+    expectedRevision: z.number().int().min(1).max(2_147_483_647),
+    requestId: z.string().uuid(),
+  })
+  .strict();
+
+export type ChatDraftConsumeRequest = z.infer<
+  typeof chatDraftConsumeRequestSchema
+>;
+
+export type ChatDraftConsume = Omit<ChatDraftConsumeRequest, "requestId"> & {
+  messageId: string;
+};
+
+export class ChatDraftConsumeConflictError extends Error {
+  readonly code = "MESSAGE_SAVE_CONFLICT";
+  readonly status = 409;
+
+  constructor() {
+    super("The saved message does not match the draft being consumed.");
+    this.name = "ChatDraftConsumeConflictError";
+  }
+}
+
+const sameReferences = (
+  left: readonly ChatDraftAttachmentReference[],
+  right: readonly ChatDraftAttachmentReference[]
+) => JSON.stringify(left) === JSON.stringify(right);
+
+export type DraftMessage = {
+  id: string;
+  content: string;
+  modelId?: string;
+  attachmentUploadIds?: string[];
+  attachmentReferences?: ChatDraftAttachmentReference[];
+};
+
+export const chatDraftMessageReceiptSchema = z
+  .object({
+    draftConsume: chatDraftConsumeRequestSchema,
+    message: z
+      .object({
+        clientRequestId: z.string().uuid(),
+        content: z.string().trim().max(50_000),
+        attachmentUploadIds: z.array(opaqueId).max(5).optional(),
+        attachmentReferences: chatDraftAttachmentReferencesSchema.optional(),
+      })
+      .strict()
+      .refine(
+        (message) =>
+          !(message.attachmentUploadIds && message.attachmentReferences),
+        { message: "Use one attachment reference format per message." }
+      )
+      .refine(
+        (message) =>
+          message.content.length > 0 ||
+          (message.attachmentUploadIds?.length ?? 0) > 0 ||
+          (message.attachmentReferences?.length ?? 0) > 0,
+        { message: "A receipt message must have text or an attachment." }
+      ),
+  })
+  .strict()
+  .refine(
+    (body) => body.draftConsume.requestId === body.message.clientRequestId,
+    { message: "The receipt must name its one message." }
+  );
+
+export type ChatDraftMessageReceiptRequest = {
+  draftConsume: ChatDraftConsume;
+  message: DraftMessage;
+};
+
+export type ChatDraftMessageReceipt =
+  | {
+      outcome: "committed";
+      messageId: string;
+      attachments: PublicMessageAttachment[];
+    }
+  | { outcome: "unchanged"; attachments: [] }
+  | { outcome: "ambiguous"; attachments: [] };
+
+type DraftReadDb = Pick<Prisma.TransactionClient, "message" | "chatComposerDraft">;
+
+async function exactExistingMessage(
+  tx: DraftReadDb,
+  input: {
+    userId: string;
+    conversationId: string;
+    message: DraftMessage;
+  }
+) {
+  const existing = await tx.message.findFirst({
+    where: {
+      id: input.message.id,
+      conversationId: input.conversationId,
+      conversation: { userId: input.userId },
+    },
+    select: {
+      role: true,
+      content: true,
+      modelId: true,
+      attachments: {
+        orderBy: { ordinal: "asc" },
+        select: {
+          uploadId: true,
+          sourceAttachmentId: true,
+        },
+      },
+    },
+  });
+  if (!existing) return false;
+  if (
+    existing.role !== "user" ||
+    existing.content !== input.message.content ||
+    existing.modelId !== (input.message.modelId ?? null)
+  ) {
+    throw new ChatDraftConsumeConflictError();
+  }
+
+  const references =
+    input.message.attachmentReferences ??
+    (input.message.attachmentUploadIds ?? []).map((uploadId) => ({ uploadId }));
+  if (existing.attachments.length !== references.length) {
+    throw new ChatDraftConsumeConflictError();
+  }
+  for (const [index, reference] of references.entries()) {
+    const bound = existing.attachments[index];
+    if (!bound) throw new ChatDraftConsumeConflictError();
+    if ("uploadId" in reference) {
+      if (bound.uploadId !== reference.uploadId) throw new ChatDraftConsumeConflictError();
+      continue;
+    }
+    if (bound.sourceAttachmentId !== reference.attachmentId) {
+      throw new ChatDraftConsumeConflictError();
+    }
+  }
+  return true;
+}
+
+async function inspectChatDraftForMessage(
+  db: DraftReadDb,
+  input: {
+    userId: string;
+    conversationId: string;
+    draftConsume: ChatDraftConsume;
+    message: DraftMessage;
+  }
+): Promise<{ replay: boolean }> {
+  if (
+    input.draftConsume.messageId !== input.message.id ||
+    (input.draftConsume.scopeKey !== CHAT_DRAFT_NEW_SCOPE &&
+      input.draftConsume.scopeKey !== input.conversationId)
+  ) {
+    throw new ChatDraftConsumeConflictError();
+  }
+  const replay = await exactExistingMessage(db, input);
+  if (replay) return { replay: true };
+  const draft = await db.chatComposerDraft.findUnique({
+    where: {
+      userId_scopeKey: {
+        userId: input.userId,
+        scopeKey: input.draftConsume.scopeKey,
+      },
+    },
+    select: { text: true, attachmentReferences: true, revision: true },
+  });
+  if (!draft) throw new ChatDraftConsumeConflictError();
+  const messageReferences = chatDraftAttachmentReferencesSchema.parse(
+    input.message.attachmentReferences ??
+      (input.message.attachmentUploadIds ?? []).map((uploadId) => ({ uploadId }))
+  );
+  if (
+    draft.revision !== input.draftConsume.expectedRevision ||
+    draft.text !== input.message.content ||
+    !sameReferences(parseStoredDraftReferences(draft.attachmentReferences), messageReferences)
+  ) {
+    throw new ChatDraftConsumeConflictError();
+  }
+  return { replay: false };
+}
+
+/**
+ * Read-only fail-fast gate used before attachment bytes are read or copied.
+ * The transaction gate below repeats the comparison under the conversation
+ * lock, so passing this check grants no write authority.
+ */
+export async function preflightChatDraftForMessage(input: {
+  userId: string;
+  conversationId: string;
+  draftConsume: ChatDraftConsume;
+  message: DraftMessage;
+}): Promise<{ replay: boolean }> {
+  const { prisma } = await import("@/lib/prisma");
+  return inspectChatDraftForMessage(prisma, input);
+}
+
+/**
+ * Verifies and consumes one durable composer draft in the same transaction as
+ * the user Message. The shared advisory lock also serialises a model-history
+ * clear and the following response-attempt claim for this conversation.
+ */
+export async function consumeChatDraftForMessage(
+  tx: Prisma.TransactionClient,
+  input: {
+    userId: string;
+    conversationId: string;
+    draftConsume: ChatDraftConsume;
+    message: DraftMessage;
+  }
+): Promise<{ replay: boolean }> {
+  await lockChatRecoveryConversation(tx, input.userId, input.conversationId);
+  const inspection = await inspectChatDraftForMessage(tx, input);
+  // The exact Message is the durable receipt for the original consume. A
+  // later draft may already occupy the same composer scope; a retry of the
+  // old request must neither reject because of it nor delete it.
+  if (inspection.replay) return inspection;
+  const removed = await tx.chatComposerDraft.deleteMany({
+    where: {
+      userId: input.userId,
+      scopeKey: input.draftConsume.scopeKey,
+      revision: input.draftConsume.expectedRevision,
+    },
+  });
+  if (removed.count !== 1) throw new ChatDraftConsumeConflictError();
+  return { replay: false };
+}
+
+/**
+ * Resolves an indeterminate Message POST without repeating a write.
+ *
+ * The browser calls this only after a timeout, network failure, or 5xx made
+ * the transaction's result unknowable. The same conversation advisory lock
+ * used by draft consumption makes the observations one serial point:
+ *
+ * - the exact Message is the durable receipt (`committed`);
+ * - no Message plus the exact original draft is a proven rollback
+ *   (`unchanged`);
+ * - every other state is deliberately `ambiguous`.
+ *
+ * No result authorises a write. In particular, `ambiguous` never guesses
+ * whether a missing draft was consumed or independently changed.
+ */
+export async function reconcileChatDraftMessageReceipt(input: {
+  userId: string;
+  conversationId: string;
+  receipt: ChatDraftMessageReceiptRequest;
+}): Promise<ChatDraftMessageReceipt> {
+  const { prisma } = await import("@/lib/prisma");
+  return prisma.$transaction(async (tx) => {
+    await lockChatRecoveryConversation(tx, input.userId, input.conversationId);
+    const conversation = await tx.conversation.findFirst({
+      where: { id: input.conversationId, userId: input.userId },
+      select: { kind: true, productKey: true },
+    });
+    if (!conversation || conversation.kind !== "chat" ||
+        conversation.productKey !== "chat") {
+      return { outcome: "ambiguous", attachments: [] };
+    }
+    if (
+      input.receipt.draftConsume.scopeKey !== CHAT_DRAFT_NEW_SCOPE &&
+      input.receipt.draftConsume.scopeKey !== input.conversationId
+    ) {
+      return { outcome: "ambiguous", attachments: [] };
+    }
+
+    try {
+      const committed = await exactExistingMessage(tx, {
+        userId: input.userId,
+        conversationId: input.conversationId,
+        message: input.receipt.message,
+      });
+      if (committed) {
+        const attachments = await tx.messageAttachment.findMany({
+          where: {
+            messageId: input.receipt.message.id,
+            userId: input.userId,
+            conversationId: input.conversationId,
+          },
+          orderBy: { ordinal: "asc" },
+          select: PUBLIC_MESSAGE_ATTACHMENT_SELECT,
+        });
+        return {
+          outcome: "committed",
+          messageId: input.receipt.message.id,
+          attachments: attachments.map(toPublicMessageAttachment),
+        };
+      }
+    } catch (error) {
+      if (error instanceof ChatDraftConsumeConflictError) {
+        return { outcome: "ambiguous", attachments: [] };
+      }
+      throw error;
+    }
+
+    const draft = await tx.chatComposerDraft.findUnique({
+      where: {
+        userId_scopeKey: {
+          userId: input.userId,
+          scopeKey: input.receipt.draftConsume.scopeKey,
+        },
+      },
+      select: { text: true, attachmentReferences: true, revision: true },
+    });
+    const messageReferences = chatDraftAttachmentReferencesSchema.parse(
+      input.receipt.message.attachmentReferences ??
+        (input.receipt.message.attachmentUploadIds ?? []).map((uploadId) => ({
+          uploadId,
+        }))
+    );
+    if (
+      draft &&
+      draft.revision === input.receipt.draftConsume.expectedRevision &&
+      draft.text === input.receipt.message.content &&
+      sameReferences(
+        parseStoredDraftReferences(draft.attachmentReferences),
+        messageReferences
+      )
+    ) {
+      return { outcome: "unchanged", attachments: [] };
+    }
+    return { outcome: "ambiguous", attachments: [] };
+  });
+}
