index 00000000..b614caf4
--- /dev/null
+++ b/lib/chatDurableAttemptStream.ts
@@ -0,0 +1,150 @@
+import "server-only";
+
+import {
+  CHAT_RESPONSE_ATTEMPT_MAX_LEASE_MS,
+  type ChatResponseAttemptRecord,
+} from "@/lib/chatResponseAttemptCore";
+import { checkpointChatResponseAttempt } from "@/lib/chatResponseAttemptPersistence";
+
+export const CHAT_DURABLE_PARTIAL_MAX_CHARACTERS = 100_000;
+export const CHAT_DURABLE_CHECKPOINT_CHARACTER_STEP = 2_048;
+export const CHAT_DURABLE_CHECKPOINT_INTERVAL_MS = 1_000;
+const LEASE_RENEWAL_HEADROOM_MS = 15_000;
+
+const durablePrefix = (content: string) =>
+  content.slice(0, CHAT_DURABLE_PARTIAL_MAX_CHARACTERS);
+
+/**
+ * Coalesces high-frequency stream chunks into serial CAS checkpoints. observe()
+ * is called only after a chunk was enqueued to the browser. flush() is the
+ * terminal barrier: the assistant Message cannot commit until every earlier
+ * visible prefix has either persisted or failed its lease/owner CAS.
+ */
+export function createChatResponseAttemptCheckpointWriter(input: {
+  userId: string;
+  assistantMessageId: string;
+  ownerId: string;
+  initialRevision: number;
+  requestedModelId: string;
+}, persistCheckpoint: typeof checkpointChatResponseAttempt = checkpointChatResponseAttempt) {
+  let revision = input.initialRevision;
+  let persistedContent = "";
+  let pendingContent: string | null = null;
+  let running: Promise<void> | null = null;
+  let scheduled: ReturnType<typeof setTimeout> | null = null;
+  let failure: unknown = null;
+  let lastStartedAt = Date.now();
+  let actualModelId: string | null = null;
+  let provider: string | null = null;
+
+  const pump = () => {
+    if (scheduled) {
+      clearTimeout(scheduled);
+      scheduled = null;
+    }
+    if (running || failure || pendingContent === null) return;
+    running = (async () => {
+      while (pendingContent !== null && !failure) {
+        const next = pendingContent;
+        pendingContent = null;
+        if (next === persistedContent) continue;
+        lastStartedAt = Date.now();
+        const updated = await persistCheckpoint({
+          userId: input.userId,
+          assistantMessageId: input.assistantMessageId,
+          ownerId: input.ownerId,
+          expectedRevision: revision,
+          partialContent: next,
+          actualModelId,
+          provider,
+          leaseExpiresAt: new Date(
+            Date.now() + CHAT_RESPONSE_ATTEMPT_MAX_LEASE_MS - LEASE_RENEWAL_HEADROOM_MS
+          ),
+        });
+        if (!updated) throw new Error("CHAT_ATTEMPT_CHECKPOINT_NOT_FOUND");
+        revision = updated.checkpointRevision;
+        persistedContent = updated.partialContent;
+      }
+    })()
+      .catch((error) => {
+        failure = error;
+      })
+      .finally(() => {
+        running = null;
+        if (pendingContent !== null && !failure) pump();
+      });
+  };
+
+  const setAttribution = (nextModelId: string, nextProvider: string) => {
+    actualModelId = nextModelId;
+    provider = nextProvider;
+  };
+
+  const observe = (content: string) => {
+    if (failure) return;
+    const next = durablePrefix(content);
+    // Never discard a prefix which was already visible to the browser. Small
+    // chunks are coalesced, but they still become pending durable state and a
+    // timer guarantees persistence even when no later chunk arrives.
+    pendingContent = next;
+    if (
+      next.length - persistedContent.length < CHAT_DURABLE_CHECKPOINT_CHARACTER_STEP &&
+      Date.now() - lastStartedAt < CHAT_DURABLE_CHECKPOINT_INTERVAL_MS
+    ) {
+      if (!scheduled) {
+        const remaining = Math.max(
+          0,
+          CHAT_DURABLE_CHECKPOINT_INTERVAL_MS - (Date.now() - lastStartedAt)
+        );
+        scheduled = setTimeout(pump, remaining);
+        scheduled.unref?.();
+      }
+      return;
+    }
+    pump();
+  };
+
+  const flush = async (content: string) => {
+    if (failure) throw failure;
+    if (scheduled) {
+      clearTimeout(scheduled);
+      scheduled = null;
+    }
+    const revisionAtFlushStart = revision;
+    pendingContent = durablePrefix(content);
+    pump();
+    while (running) await running;
+    if (failure) throw failure;
+    // Even when no new characters arrived since the last coalesced write, the
+    // terminal path needs a fresh owner/revision/DB-clock CAS. Otherwise an
+    // expired writer whose final prefix already matched could skip persistence
+    // entirely and continue into billing or Message side effects.
+    if (revision === revisionAtFlushStart) {
+      const updated = await persistCheckpoint({
+        userId: input.userId,
+        assistantMessageId: input.assistantMessageId,
+        ownerId: input.ownerId,
+        expectedRevision: revision,
+        partialContent: durablePrefix(content),
+        actualModelId,
+        provider,
+        leaseExpiresAt: new Date(
+          Date.now() + CHAT_RESPONSE_ATTEMPT_MAX_LEASE_MS - LEASE_RENEWAL_HEADROOM_MS
+        ),
+      });
+      if (!updated) throw new Error("CHAT_ATTEMPT_CHECKPOINT_NOT_FOUND");
+      revision = updated.checkpointRevision;
+      persistedContent = updated.partialContent;
+    }
+    return { revision, partialContent: persistedContent, actualModelId, provider };
+  };
+
+  return { setAttribution, observe, flush };
+}
+
+export type ChatResponseAttemptCheckpointWriter = ReturnType<
+  typeof createChatResponseAttemptCheckpointWriter
+>;
+
+export const attemptTerminalContent = (record: Pick<ChatResponseAttemptRecord, "partialContent">) =>
+  durablePrefix(record.partialContent);
diff --git a/lib/chatDurableRecoveryAccess.ts b/lib/chatDurableRecoveryAccess.ts
new file mode 100644
index 00000000..5e86749e
--- /dev/null
+++ b/lib/chatDurableRecoveryAccess.ts
@@ -0,0 +1,81 @@
+import "server-only";
+
+import { autoAvailabilityFor } from "@/lib/autoAvailability";
+import { chatSurfaceAvailable } from "@/lib/autoProductBoundary";
+import { CHAT_DRAFT_NEW_SCOPE } from "@/lib/chatComposerDraftCore";
+import {
+  conversationKindNotSupportedResponse,
+  isChatConversationKind,
+} from "@/lib/conversationKindGuard";
+import {
+  conversationLockedResponse,
+  hasConversationUnlockGrant,
+} from "@/lib/conversationLock";
+import { CHAT_PRODUCT_KEY } from "@/lib/conversationProduct";
+import { prisma } from "@/lib/prisma";
+
+export type ChatRecoveryScopeAccess =
+  | { ok: true; conversationId: string | null }
+  | { ok: false; response: Response };
+
+const jsonError = (error: string, code: string, status: number) =>
+  Response.json(
+    { error, code },
+    { status, headers: { "Cache-Control": "no-store" } }
+  );
+
+/**
+ * Authorizes only the durable Chat surface. Existing rows use their stored
+ * product and remain readable after a cohort change; only the unbound `new`
+ * scope asks the entry gate.
+ */
+export async function authorizeChatRecoveryScope(input: {
+  request: Request;
+  userId: string;
+  scopeKey: string;
+}): Promise<ChatRecoveryScopeAccess> {
+  if (input.scopeKey === CHAT_DRAFT_NEW_SCOPE) {
+    const availability = await autoAvailabilityFor(input.userId);
+    return chatSurfaceAvailable(availability)
+      ? { ok: true, conversationId: null }
+      : {
+          ok: false,
+          response: jsonError("Not found.", "CHAT_RECOVERY_SCOPE_NOT_FOUND", 404),
+        };
+  }
+
+  const conversation = await prisma.conversation.findFirst({
+    where: { id: input.scopeKey, userId: input.userId },
+    select: { password: true, productKey: true, kind: true },
+  });
+  if (!conversation) {
+    return {
+      ok: false,
+      response: jsonError("Conversation not found.", "CONVERSATION_NOT_FOUND", 404),
+    };
+  }
+  if (!isChatConversationKind(conversation.kind)) {
+    return { ok: false, response: conversationKindNotSupportedResponse() };
+  }
+  if (conversation.productKey !== CHAT_PRODUCT_KEY) {
+    return {
+      ok: false,
+      response: jsonError(
+        "This operation is available only for Tomverse Chat conversations.",
+        "CHAT_RECOVERY_PRODUCT_NOT_SUPPORTED",
+        409
+      ),
+    };
+  }
+  if (
+    !hasConversationUnlockGrant(
+      input.request,
+      input.userId,
+      input.scopeKey,
+      conversation.password
+    )
+  ) {
+    return { ok: false, response: conversationLockedResponse() };
+  }
+  return { ok: true, conversationId: input.scopeKey };
+}
diff --git a/lib/chatDurableSourceMessage.ts b/lib/chatDurableSourceMessage.ts
new file mode 100644
index 00000000..ee53244f
--- /dev/null
+++ b/lib/chatDurableSourceMessage.ts
@@ -0,0 +1,110 @@
+import "server-only";
+
+import { prisma } from "@/lib/prisma";
+
+type DurableRequestAttachment = {
+  attachmentId?: unknown;
+  uploadId?: unknown;
+};
+
+type DurableRequestMessage = {
+  id?: string;
+  role: "user" | "assistant";
+  content: string;
+  attachments?: unknown[];
+};
+
+export class ChatSourceMessageMismatchError extends Error {
+  readonly code = "CHAT_SOURCE_MESSAGE_MISMATCH";
+  readonly status = 409;
+
+  constructor() {
+    super("The persisted source message does not match this Chat request.");
+    this.name = "ChatSourceMessageMismatchError";
+  }
+}
+
+/**
+ * Binds a paid durable execution to the exact user Message already committed
+ * by the pre-save route. Text and ordered opaque attachment identities are
+ * compared; browser-supplied names and media metadata are never evidence.
+ */
+export async function verifyDurableChatSourceMessage(input: {
+  userId: string;
+  conversationId: string;
+  sourceUserMessageId: string;
+  messages: DurableRequestMessage[];
+}) {
+  const latestUserMessage = [...input.messages]
+    .reverse()
+    .find((message) => message.role === "user");
+  if (!latestUserMessage || latestUserMessage.id !== input.sourceUserMessageId) {
+    throw new ChatSourceMessageMismatchError();
+  }
+
+  const persisted = await prisma.message.findFirst({
+    where: {
+      id: input.sourceUserMessageId,
+      conversationId: input.conversationId,
+      role: "user",
+      conversation: { userId: input.userId },
+    },
+    select: {
+      id: true,
+      content: true,
+      attachments: {
+        orderBy: { ordinal: "asc" },
+        select: {
+          id: true,
+          uploadId: true,
+          userId: true,
+          conversationId: true,
+        },
+      },
+    },
+  });
+  if (!persisted || persisted.content !== latestUserMessage.content) {
+    throw new ChatSourceMessageMismatchError();
+  }
+
+  const requested = Array.isArray(latestUserMessage.attachments)
+    ? (latestUserMessage.attachments as DurableRequestAttachment[])
+    : [];
+  if (requested.length !== persisted.attachments.length) {
+    throw new ChatSourceMessageMismatchError();
+  }
+  for (const [index, reference] of requested.entries()) {
+    const attachment = persisted.attachments[index];
+    if (
+      !attachment ||
+      attachment.userId !== input.userId ||
+      attachment.conversationId !== input.conversationId
+    ) {
+      throw new ChatSourceMessageMismatchError();
+    }
+    if (
+      typeof reference.attachmentId === "string" &&
+      reference.attachmentId.length > 0 &&
+      reference.uploadId === undefined
+    ) {
+      // The conversation/detail and message-save responses hand the browser
+      // this newly bound row id. `sourceAttachmentId` remains provenance for
+      // draft replay/copy validation; it is not the identity of the current
+      // persisted turn the provider is about to receive.
+      if (attachment.id !== reference.attachmentId) {
+        throw new ChatSourceMessageMismatchError();
+      }
+      continue;
+    }
+    if (
+      typeof reference.uploadId === "string" &&
+      reference.uploadId.length > 0 &&
+      reference.attachmentId === undefined &&
+      attachment.uploadId === reference.uploadId
+    ) {
+      continue;
+    }
+    throw new ChatSourceMessageMismatchError();
+  }
+  return { id: persisted.id };
+}
diff --git a/lib/chatResponseAttemptCore.ts b/lib/chatResponseAttemptCore.ts
new file mode 100644
index 00000000..bc6165fe
--- /dev/null
+++ b/lib/chatResponseAttemptCore.ts
@@ -0,0 +1,305 @@
+import { createHash } from "node:crypto";
+import { z } from "zod";
+
+export const CHAT_ATTEMPT_ID_REUSED = "CHAT_ATTEMPT_ID_REUSED" as const;
+export const CHAT_ATTEMPT_REVISION_CONFLICT = "CHAT_ATTEMPT_REVISION_CONFLICT" as const;
+export const CHAT_RESPONSE_ATTEMPT_MAX_LEASE_MS = 5 * 60 * 1_000;
+
+export const CHAT_RESPONSE_ATTEMPT_ACTIVE_STATUSES = ["claimed", "streaming"] as const;
+export const CHAT_RESPONSE_ATTEMPT_TERMINAL_STATUSES = [
+  "completed",
+  "failed",
+  "cancelled",
+] as const;
+export const CHAT_RESPONSE_ATTEMPT_STATUSES = [
+  ...CHAT_RESPONSE_ATTEMPT_ACTIVE_STATUSES,
+  ...CHAT_RESPONSE_ATTEMPT_TERMINAL_STATUSES,
+] as const;
+export const CHAT_RESPONSE_ATTEMPT_FINISH_REASONS = [
+  "stop",
+  "length",
+  "content_filter",
+  "tool_call",
+  "cancelled",
+  "error",
+] as const;
+export const CHAT_RESPONSE_ATTEMPT_FAILURE_CODES = [
+  "provider_unavailable",
+  "model_unavailable",
+  "request_refused",
+  "stream_interrupted",
+  "worker_lease_expired",
+  "internal_error",
+] as const;
+export const chatResponseAttemptStatusSchema = z.enum(CHAT_RESPONSE_ATTEMPT_STATUSES);
+export const chatResponseAttemptTerminalStatusSchema = z.enum(
+  CHAT_RESPONSE_ATTEMPT_TERMINAL_STATUSES
+);
+export const chatResponseAttemptFinishReasonSchema = z.enum(
+  CHAT_RESPONSE_ATTEMPT_FINISH_REASONS
+);
+export const chatResponseAttemptFailureCodeSchema = z.enum(
+  CHAT_RESPONSE_ATTEMPT_FAILURE_CODES
+);
+
+export type ChatResponseAttemptStatus = (typeof CHAT_RESPONSE_ATTEMPT_STATUSES)[number];
+export type ChatResponseAttemptTerminalStatus =
+  (typeof CHAT_RESPONSE_ATTEMPT_TERMINAL_STATUSES)[number];
+export type ChatResponseAttemptFinishReason =
+  (typeof CHAT_RESPONSE_ATTEMPT_FINISH_REASONS)[number];
+export type ChatResponseAttemptFailureCode =
+  (typeof CHAT_RESPONSE_ATTEMPT_FAILURE_CODES)[number];
+
+const idSchema = z.string().trim().min(1).max(64).regex(/^[A-Za-z0-9_-]+$/);
+const modelIdSchema = z.string().trim().min(1).max(120);
+const sha256Schema = z.string().regex(/^[0-9a-f]{64}$/);
+
+export const chatResponseAttemptIdSchema = idSchema;
+
+export const chatResponseAttemptClaimSchema = z
+  .object({
+    assistantMessageId: idSchema,
+    conversationId: idSchema,
+    sourceUserMessageId: idSchema,
+    requestedModelId: modelIdSchema,
+    requestPayloadDigest: sha256Schema,
+    ownerId: z.string().trim().min(1).max(128),
+    leaseExpiresAt: z.date(),
+  })
+  .strict();
+
+export type ChatResponseAttemptClaimInput = z.infer<
+  typeof chatResponseAttemptClaimSchema
+>;
+
+export type ChatResponseAttemptIdentity = {
+  assistantMessageId: string;
+  userId: string;
+  conversationId: string;
+  sourceUserMessageId: string;
+  fingerprint: string;
+  requestedModelId: string;
+};
+
+export type ChatResponseAttemptRecord = ChatResponseAttemptIdentity & {
+  actualModelId: string | null;
+  provider: string | null;
+  status: ChatResponseAttemptStatus;
+  partialContent: string;
+  checkpointRevision: number;
+  ownerId: string;
+  leaseExpiresAt: Date;
+  finishReason: ChatResponseAttemptFinishReason | null;
+  failureCode: ChatResponseAttemptFailureCode | null;
+  terminalAt: Date | null;
+  createdAt: Date;
+  updatedAt: Date;
+};
+
+const fingerprintPart = (value: string) => `${Buffer.byteLength(value, "utf8")}:${value}`;
+
+const canonicalJson = (value: unknown): string => {
+  if (value === null || typeof value !== "object") return JSON.stringify(value);
+  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
+  return `{${Object.entries(value as Record<string, unknown>)
+    .filter(([, entry]) => entry !== undefined)
+    .sort(([left], [right]) => left.localeCompare(right))
+    .map(([key, entry]) => `${JSON.stringify(key)}:${canonicalJson(entry)}`)
+    .join(",")}}`;
+};
+
+/**
+ * Digests the replay-significant request fields without storing prompt text.
+ * Object keys are sorted, while message and attachment array order remains
+ * significant. Ephemeral admission/worker tokens must not be included by the
+ * caller: refreshing one must not turn the same user action into a new
+ * execution identity.
+ */
+export function chatResponseAttemptRequestPayloadDigest(value: unknown): string {
+  return createHash("sha256")
+    .update("chat-response-request.v1\0")
+    .update(canonicalJson(value))
+    .digest("hex");
+}
+
+/** Versioned and length-delimited; no prompt text is persisted by this function. */
+export function chatResponseAttemptFingerprint(input: {
+  conversationId: string;
+  sourceUserMessageId: string;
+  requestedModelId: string;
+  requestPayloadDigest: string;
+}): string {
+  const parsed = chatResponseAttemptClaimSchema.pick({
+    conversationId: true,
+    sourceUserMessageId: true,
+    requestedModelId: true,
+    requestPayloadDigest: true,
+  }).parse({
+    conversationId: input.conversationId,
+    sourceUserMessageId: input.sourceUserMessageId,
+    requestedModelId: input.requestedModelId,
+    requestPayloadDigest: input.requestPayloadDigest,
+  });
+  const material = [
+    "chat-response-attempt.v1",
+    parsed.conversationId,
+    parsed.sourceUserMessageId,
+    parsed.requestedModelId,
+    parsed.requestPayloadDigest,
+  ]
+    .map(fingerprintPart)
+    .join("|");
+  return createHash("sha256").update(material).digest("hex");
+}
+
+export type AttemptClaimDecision =
+  | { action: "create" }
+  | { action: "reattach" }
+  | { action: "conflict"; code: typeof CHAT_ATTEMPT_ID_REUSED };
+
+export function decideAttemptClaim(
+  existing: ChatResponseAttemptIdentity | null,
+  requested: ChatResponseAttemptIdentity
+): AttemptClaimDecision {
+  if (!existing) return { action: "create" };
+  const same =
+    existing.assistantMessageId === requested.assistantMessageId &&
+    existing.userId === requested.userId &&
+    existing.conversationId === requested.conversationId &&
+    existing.sourceUserMessageId === requested.sourceUserMessageId &&
+    existing.fingerprint === requested.fingerprint &&
+    existing.requestedModelId === requested.requestedModelId;
+  return same
+    ? { action: "reattach" }
+    : { action: "conflict", code: CHAT_ATTEMPT_ID_REUSED };
+}
+
+export type AttemptCasRefusal =
+  | "terminal"
+  | "revision_conflict"
+  | "owner_mismatch"
+  | "lease_expired"
+  | "lease_too_long"
+  | "committed_prefix_changed";
+
+export function validateAttemptLease(input: {
+  now: Date;
+  leaseExpiresAt: Date;
+}): "valid" | "lease_expired" | "lease_too_long" {
+  const now = input.now.getTime();
+  const expires = input.leaseExpiresAt.getTime();
+  if (!Number.isFinite(now) || !Number.isFinite(expires) || expires <= now) {
+    return "lease_expired";
+  }
+  return expires - now <= CHAT_RESPONSE_ATTEMPT_MAX_LEASE_MS
+    ? "valid"
+    : "lease_too_long";
+}
+
+export function validateAttemptTerminalMetadata(input: {
+  status: ChatResponseAttemptTerminalStatus;
+  finishReason: ChatResponseAttemptFinishReason | null;
+  failureCode: ChatResponseAttemptFailureCode | null;
+}): boolean {
+  if (input.status === "failed") {
+    return input.finishReason === "error" && input.failureCode !== null;
+  }
+  if (input.status === "cancelled") {
+    return input.finishReason === "cancelled" && input.failureCode === null;
+  }
+  return (
+    input.failureCode === null &&
+    input.finishReason !== "error" &&
+    input.finishReason !== "cancelled"
+  );
+}
+
+type AttemptCasDecision =
+  | { action: "update"; nextRevision: number }
+  | { action: "refuse"; reason: AttemptCasRefusal };
+
+function commonAttemptCas(input: {
+  status: ChatResponseAttemptStatus;
+  checkpointRevision: number;
+  expectedRevision: number;
+  ownerId: string;
+  expectedOwnerId: string;
+  leaseExpiresAt: Date;
+  now: Date;
+}): AttemptCasDecision {
+  if ((CHAT_RESPONSE_ATTEMPT_TERMINAL_STATUSES as readonly string[]).includes(input.status)) {
+    return { action: "refuse", reason: "terminal" };
+  }
+  if (input.checkpointRevision !== input.expectedRevision) {
+    return { action: "refuse", reason: "revision_conflict" };
+  }
+  if (input.ownerId !== input.expectedOwnerId) {
+    return { action: "refuse", reason: "owner_mismatch" };
+  }
+  const lease = validateAttemptLease(input);
+  if (lease !== "valid") {
+    return { action: "refuse", reason: lease };
+  }
+  if (input.checkpointRevision >= 2_147_483_647) {
+    return { action: "refuse", reason: "revision_conflict" };
+  }
+  return { action: "update", nextRevision: input.checkpointRevision + 1 };
+}
+
+export function decideAttemptCheckpoint(input: {
+  status: ChatResponseAttemptStatus;
+  checkpointRevision: number;
+  expectedRevision: number;
+  ownerId: string;
+  expectedOwnerId: string;
+  leaseExpiresAt: Date;
+  now: Date;
+  committedContent: string;
+  nextContent: string;
+}): AttemptCasDecision {
+  const decision = commonAttemptCas(input);
+  if (decision.action === "refuse") return decision;
+  if (!input.nextContent.startsWith(input.committedContent)) {
+    return { action: "refuse", reason: "committed_prefix_changed" };
+  }
+  return decision;
+}
+
+export function decideAttemptTerminal(input: {
+  status: ChatResponseAttemptStatus;
+  checkpointRevision: number;
+  expectedRevision: number;
+  ownerId: string;
+  expectedOwnerId: string;
+  leaseExpiresAt: Date;
+  now: Date;
+  committedContent: string;
+  finalContent: string;
+  terminalStatus: ChatResponseAttemptTerminalStatus;
+}): AttemptCasDecision {
+  const decision = commonAttemptCas(input);
+  if (decision.action === "refuse") return decision;
+  if (!input.finalContent.startsWith(input.committedContent)) {
+    return { action: "refuse", reason: "committed_prefix_changed" };
+  }
+  return decision;
+}
+
+export function publicChatResponseAttempt(record: ChatResponseAttemptRecord) {
+  return {
+    assistantMessageId: record.assistantMessageId,
+    conversationId: record.conversationId,
+    sourceUserMessageId: record.sourceUserMessageId,
+    requestedModelId: record.requestedModelId,
+    actualModelId: record.actualModelId,
+    provider: record.provider,
+    status: record.status,
+    partialContent: record.partialContent,
+    checkpointRevision: record.checkpointRevision,
+    finishReason: record.finishReason,
+    failureCode: record.failureCode,
+    terminalAt: record.terminalAt?.toISOString() ?? null,
+    createdAt: record.createdAt.toISOString(),
+    updatedAt: record.updatedAt.toISOString(),
+  };
+}
