+// One durable authenticated Chat composer draft per account and logical scope.
+// `scopeKey` is either "new" or the conversation id. Attachment references
+// are ordered opaque ids only; route validation owns their exact JSON shape.
+model ChatComposerDraft {
+  id                   String       @id @default(cuid())
+  userId               String
+  scopeKey             String
+  conversationId       String?
+  text                  String       @default("")
+  attachmentReferences Json
+  revision              Int          @default(1)
+  createdAt             DateTime     @default(now())
+  updatedAt             DateTime     @updatedAt
+
+  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)
