+  assistantMessageId  String   @id
+  userId              String
+  conversationId      String
+  sourceUserMessageId String
+  fingerprint         String
+  requestedModelId    String
+  actualModelId       String?
+  provider            String?
+  status              String   @default("claimed")
+  partialContent      String   @default("")
+  checkpointRevision  Int      @default(0)
+  ownerId             String
+  leaseExpiresAt      DateTime
+  finishReason        String?
+  failureCode         String?
+  terminalAt          DateTime?
+  createdAt           DateTime @default(now())
+  updatedAt           DateTime @updatedAt
+
